CREATE TABLE public.cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_number text NOT NULL DEFAULT ('DB-' || upper(substr(gen_random_uuid()::text,1,8))) UNIQUE, owner_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL CHECK (length(name) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '', investigator text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active','On hold','Closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.cases TO authenticated; GRANT ALL ON public.cases TO service_role;
ALTER TABLE public.cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY cases_read ON public.cases FOR SELECT TO authenticated USING (owner_id=auth.uid());
CREATE POLICY cases_insert ON public.cases FOR INSERT TO authenticated WITH CHECK (owner_id=auth.uid());
CREATE POLICY cases_update ON public.cases FOR UPDATE TO authenticated USING (owner_id=auth.uid()) WITH CHECK (owner_id=auth.uid());
CREATE TABLE public.evidence (id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES public.cases(id), owner_id uuid NOT NULL DEFAULT auth.uid(), filename text NOT NULL, file_type text NOT NULL, file_size bigint NOT NULL CHECK (file_size > 0 AND file_size <= 52428800), description text NOT NULL DEFAULT '', uploader text NOT NULL, storage_path text NOT NULL UNIQUE, sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'), processing_status text NOT NULL DEFAULT 'UNPROCESSED' CHECK (processing_status='UNPROCESSED'), validation_status text NOT NULL DEFAULT 'UNPROCESSED' CHECK (validation_status='UNPROCESSED'), uploaded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,sha256));
GRANT SELECT, INSERT ON public.evidence TO authenticated; GRANT ALL ON public.evidence TO service_role;
ALTER TABLE public.evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_read ON public.evidence FOR SELECT TO authenticated USING (owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.cases c WHERE c.id=case_id AND c.owner_id=auth.uid()));
CREATE POLICY evidence_insert ON public.evidence FOR INSERT TO authenticated WITH CHECK (owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.cases c WHERE c.id=case_id AND c.owner_id=auth.uid()) AND storage_path LIKE auth.uid()::text || '/' || case_id::text || '/%');
CREATE TABLE public.activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, case_id uuid NOT NULL REFERENCES public.cases(id), action text NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity TO authenticated; GRANT ALL ON public.activity TO service_role;
ALTER TABLE public.activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activity FOR SELECT TO authenticated USING (owner_id=auth.uid());
CREATE FUNCTION public.record_case_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity(owner_id,case_id,action,detail) VALUES(NEW.owner_id,NEW.id,CASE WHEN TG_OP='INSERT' THEN 'Case created' ELSE 'Case updated' END, NEW.name); RETURN NEW; END $$;
CREATE TRIGGER case_activity AFTER INSERT OR UPDATE ON public.cases FOR EACH ROW EXECUTE FUNCTION public.record_case_activity();
CREATE FUNCTION public.record_evidence_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity(owner_id,case_id,action,detail) VALUES(NEW.owner_id,NEW.case_id,'Evidence uploaded',NEW.filename); RETURN NEW; END $$;
CREATE TRIGGER evidence_activity AFTER INSERT ON public.evidence FOR EACH ROW EXECUTE FUNCTION public.record_evidence_activity();
CREATE POLICY originals_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='evidence-originals' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.cases c WHERE c.id::text=(storage.foldername(name))[2] AND c.owner_id=auth.uid()));
CREATE POLICY originals_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='evidence-originals' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.cases c WHERE c.id::text=(storage.foldername(name))[2] AND c.owner_id=auth.uid()));